from typing import List, Any

def common_in_nested_lists(nestedlist: List[List[Any]]) -> List[Any]:
    if not nestedlist:
        return []
    common = set(nestedlist[0])
    for sublist in nestedlist[1:]:
        common.intersection_update(sublist)
    return list(common)
